// Lightweight Supabase client — no npm package needed
const sb = (() => {
  const h = { "Content-Type": "application/json", "apikey": SUPABASE_ANON, "Authorization": `Bearer ${SUPABASE_ANON}` };
  const rest = (table) => `${SUPABASE_URL}/rest/v1/${table}`;
  const q = async (method, table, opts = {}) => {
    const { filter, body, upsertOn } = opts;
    let url = rest(table);
    if (filter) url += "?" + filter;
    const headers = { ...h };
    if (method === "POST" && upsertOn) headers["Prefer"] = "resolution=merge-duplicates,return=minimal";
    else if (method === "POST") headers["Prefer"] = "return=minimal";
    const res = await fetch(url, { method, headers, ...(body ? { body: JSON.stringify(body) } : {}) });
    if (method === "GET") { const d = await res.json(); return { data: d, error: null }; }
    return { data: null, error: res.ok ? null : await res.text() };
  };
  const from = (table) => ({
    select: (cols = "*") => q("GET", table, { filter: `select=${cols}` }),
    insert: (rows) => q("POST", table, { body: Array.isArray(rows) ? rows : [rows] }),
    upsert: (rows, opts = {}) => q("POST", table, { body: Array.isArray(rows) ? rows : [rows], upsertOn: opts.onConflict }),
    delete: () => ({
      eq:  (col, val) => q("DELETE", table, { filter: `${col}=eq.${encodeURIComponent(val)}` }),
      neq: (col, val) => q("DELETE", table, { filter: `${col}=neq.${encodeURIComponent(val)}` }),
    }),
  });
  const storage = {
    upload: async (bucket, path, file) => {
      // Supabase Storage expects the raw file body with Content-Type set to the file's MIME type
      const contentType = file.type && file.type !== "" ? file.type : "application/octet-stream";
      const encodedPath = path.split('/').map(encodeURIComponent).join('/');
      const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${bucket}/${encodedPath}`, {
        method: "POST",
        headers: {
          "apikey": SUPABASE_ANON,
          "Authorization": `Bearer ${SUPABASE_ANON}`,
          "Content-Type": contentType,
          "x-upsert": "true",
          "Cache-Control": "3600",
        },
        body: file,
      });
      const text = await res.text();
      if (!res.ok) console.error("Storage upload error:", res.status, text);
      return { error: res.ok ? null : text };
    },
    remove: async (bucket, paths) => {
      const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${bucket}`, {
        method: "DELETE",
        headers: { "apikey": SUPABASE_ANON, "Authorization": `Bearer ${SUPABASE_ANON}`, "Content-Type": "application/json" },
        body: JSON.stringify({ prefixes: paths }),
      });
      return { error: res.ok ? null : await res.text() };
    },
    getPublicUrl: (bucket, path) => `${SUPABASE_URL}/storage/v1/object/public/${bucket}/${path.split('/').map(encodeURIComponent).join('/')}`,
  };
  return { from, storage };
})();

// ─── Password hashing ───────────────────────────────────────────────────────────
async function hashPassword(password) {
  const encoder = new TextEncoder();
  const data = encoder.encode(password);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
}
// Default password hash (for "pass123")
let DEFAULT_HASH = "";
hashPassword("pass123").then(h => { DEFAULT_HASH = h; });

// ─── File accept type constants (avoids wildcard slash-star in JSX string attributes) ─────
const ACCEPT_IMAGES = ["image/jpeg","image/png","image/gif","image/webp"].join(",");
const ACCEPT_VIDEO  = ["video/mp4","video/webm","video/ogg","video/quicktime"].join(",");
const ACCEPT_IMG_DOCS = ACCEPT_IMAGES + ",.pdf,.doc,.docx";

// ─── Responsive hook ────────────────────────────────────────────────────────────
function useWindowWidth() {
  const [w, setW] = React.useState(window.innerWidth);
  React.useEffect(() => {
    const handler = () => setW(window.innerWidth);
    window.addEventListener("resize", handler);
    return () => window.removeEventListener("resize", handler);
  }, []);
  return w;
}
// Convenience: returns responsive grid style
// cols: number of columns on desktop, collapses to 1 on mobile
function rGrid(cols, gap = 14, mobileGap = 10) {
  const w = window.innerWidth;
  const isMobile = w <= 1024;
  const colMap = {
    2: "1fr 1fr",
    3: "1fr 1fr 1fr",
    4: "1fr 1fr 1fr 1fr",
  };
  return {
    display: "grid",
    gridTemplateColumns: isMobile ? "1fr" : (colMap[cols] || `repeat(${cols},1fr)`),
    gap: isMobile ? mobileGap : gap,
  };
}

// ─── Mobile card helper ─────────────────────────────────────────────────────────
// Renders a key-value card for mobile table rows
function MobileCard({ children, style }) {
  const s = Object.assign({
    background:"rgba(255,255,255,0.04)",
    border:"1px solid rgba(255,255,255,0.08)",
    borderRadius:12,
    padding:"14px 16px",
    marginBottom:10,
    display:"flex",
    flexDirection:"column",
    gap:8,
  }, style||{});
  return <div style={s}>{children}</div>;
}
function MobileCardRow({ label, value }) {
  return (
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:12}}>
      <span style={{fontSize:11,fontWeight:700,letterSpacing:.5,color:"rgba(255,255,255,0.4)",textTransform:"uppercase",flexShrink:0}}>{label}</span>
      <span style={{fontSize:13,color:"rgba(255,255,255,0.9)",textAlign:"right",minWidth:0,wordBreak:"break-word"}}>{value}</span>
    </div>
  );
}

