// ─── Notification Bell Component ─────────────────────────────────────────────
function NotificationBell({ notifications, onNavigate, Z, font }) {
  const [open, setOpen] = useState(false);
  const count = notifications.length;
  const urgent = notifications.filter(n=>n.urgent).length;

  const typeIcons = { module:"📚", document:"📄", dse:"🖥️", training:"🎓", report:"📊", staff:"👥" };

  // Use fixed colours so dropdown is readable in both light and dark mode
  const dropBg    = "#1e2d5a";
  const dropBorder= "rgba(255,255,255,0.12)";
  const dropTitle = "#ffffff";
  const dropMuted = "#94a3b8";
  const dropHover = "rgba(255,255,255,0.06)";
  const dropHoverUrgent = "rgba(239,68,68,0.15)";

  const handleClick = (n) => {
    setOpen(false);
    if (n.nav && onNavigate) onNavigate(n.nav);
  };

  return (
    <div style={{position:"relative"}}>
      <button
        onClick={()=>setOpen(s=>!s)}
        style={{position:"relative",background:open?Z.borderMd:Z.overlay,border:`1px solid ${open?Z.muted:Z.borderMd}`,borderRadius:10,width:38,height:38,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,transition:"all .2s",flexShrink:0}}>
        🔔
        {count>0 && (
          <span style={{position:"absolute",top:-4,right:-4,background:urgent>0?"#ef4444":Z.amber,color:"#fff",borderRadius:99,minWidth:18,height:18,fontSize:10,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center",padding:"0 4px",border:"2px solid "+Z.navyDk,lineHeight:1}}>
            {count>9?"9+":count}
          </span>
        )}
      </button>

      {open && (
        <>
          <div onClick={()=>setOpen(false)} style={{position:"fixed",inset:0,zIndex:998}}/>
          <div style={{position:"absolute",right:0,top:44,width:340,maxHeight:440,overflowY:"auto",background:dropBg,border:`1px solid ${dropBorder}`,borderRadius:14,boxShadow:"0 20px 60px rgba(0,0,0,.5)",zIndex:999}}>
            <div style={{padding:"12px 16px",borderBottom:`1px solid ${dropBorder}`,display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,background:dropBg}}>
              <span style={{fontWeight:800,fontSize:14,color:dropTitle}}>Notifications</span>
              {count>0
                ? <span style={{fontSize:11,color:dropMuted}}>{count} action{count!==1?"s":""} pending</span>
                : <span style={{fontSize:11,color:"#34d399"}}>All up to date ✓</span>
              }
            </div>
            {count===0 ? (
              <div style={{padding:28,textAlign:"center"}}>
                <div style={{fontSize:32,marginBottom:8}}>✅</div>
                <p style={{color:dropMuted,fontSize:13,margin:0}}>No outstanding actions</p>
              </div>
            ) : (
              <div>
                {notifications.map((n,i)=>{
                  const clickable = !!(n.nav && onNavigate);
                  return (
                    <div key={i}
                      onClick={()=>handleClick(n)}
                      style={{padding:"12px 16px",borderBottom:`1px solid ${dropBorder}`,display:"flex",gap:10,alignItems:"flex-start",background:n.urgent?"rgba(239,68,68,0.08)":"transparent",cursor:clickable?"pointer":"default",transition:"background .15s"}}
                      onMouseEnter={e=>{ if(clickable) e.currentTarget.style.background=n.urgent?dropHoverUrgent:dropHover; }}
                      onMouseLeave={e=>{ e.currentTarget.style.background=n.urgent?"rgba(239,68,68,0.08)":"transparent"; }}>
                      <span style={{fontSize:18,flexShrink:0,marginTop:1}}>{typeIcons[n.type]||"📌"}</span>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontSize:13,fontWeight:700,color:n.urgent?"#fca5a5":dropTitle,lineHeight:1.4}}>{n.title}</div>
                        {n.detail && <div style={{fontSize:11,color:dropMuted,marginTop:2,lineHeight:1.4}}>{n.detail}</div>}
                      </div>
                      <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:4,flexShrink:0}}>
                        {n.urgent && <span style={{fontSize:10,color:"#f87171",fontWeight:700}}>URGENT</span>}
                        {clickable && <span style={{fontSize:11,color:"#60a5fa",fontWeight:600}}>Go →</span>}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ─── Risk Assessment Builder ──────────────────────────────────────────────────
const LIKELIHOOD_LABELS = ["Rare","Unlikely","Possible","Likely","Almost Certain"];
const SEVERITY_LABELS   = ["Negligible","Minor","Moderate","Major","Catastrophic"];

function riskLevel(l, s) {
  const score = l * s;
  if (score >= 15) return { label:"Very High", color:"#dc2626", bg:"rgba(220,38,38,0.18)", text:"#fca5a5" };
  if (score >= 10) return { label:"High",      color:"#f97316", bg:"rgba(249,115,22,0.18)", text:"#fdba74" };
  if (score >= 5)  return { label:"Medium",    color:"#f59e0b", bg:"rgba(245,158,11,0.18)", text:"#fde68a" };
  if (score >= 3)  return { label:"Low",       color:"#22c55e", bg:"rgba(34,197,94,0.18)",  text:"#86efac" };
  return              { label:"Very Low",  color:"#10b981", bg:"rgba(16,185,129,0.18)", text:"#6ee7b7" };
}

function RiskMatrix({ value, onChange, Z, font, label }) {
  // value = {likelihood: 1-5, severity: 1-5}
  const L = value.likelihood || 0;
  const S = value.severity   || 0;
  const rl = L && S ? riskLevel(L, S) : null;

  return (
    <div>
      <div style={{fontSize:11,fontWeight:700,letterSpacing:.5,color:Z.muted,marginBottom:10,textTransform:"uppercase"}}>{label}</div>
      {/* Grid: rows = severity (5 top → 1 bottom), cols = likelihood (1 left → 5 right) */}
      <div style={{display:"inline-block",border:`1px solid ${Z.borderMd}`,borderRadius:10,overflow:"hidden",userSelect:"none"}}>
        {/* Column headers */}
        <div style={{display:"grid",gridTemplateColumns:"60px repeat(5,44px)"}}>
          <div style={{background:Z.overlay,padding:"6px 4px",fontSize:9,fontWeight:700,color:Z.muted,display:"flex",alignItems:"flex-end",justifyContent:"center",borderBottom:`1px solid ${Z.borderMd}`}}>
            <span style={{writingMode:"horizontal-tb",textAlign:"center",lineHeight:1.2}}>SEVERITY →<br/>LIKELIHOOD ↓</span>
          </div>
          {LIKELIHOOD_LABELS.map((lbl,i)=>(
            <div key={i} style={{background:Z.overlay,padding:"4px 2px",fontSize:9,fontWeight:700,color:Z.muted,textAlign:"center",borderBottom:`1px solid ${Z.borderMd}`,borderLeft:`1px solid ${Z.borderMd}`,lineHeight:1.2}}>
              {i+1}<br/><span style={{fontWeight:400,fontSize:8}}>{lbl}</span>
            </div>
          ))}
        </div>
        {/* Rows: severity 5→1 */}
        {[5,4,3,2,1].map(sev=>(
          <div key={sev} style={{display:"grid",gridTemplateColumns:"60px repeat(5,44px)"}}>
            {/* Row label */}
            <div style={{background:Z.overlay,padding:"4px 6px",fontSize:9,fontWeight:700,color:Z.muted,display:"flex",alignItems:"center",justifyContent:"flex-end",borderTop:sev<5?`1px solid ${Z.borderMd}`:"none",textAlign:"right",lineHeight:1.2}}>
              {sev} {SEVERITY_LABELS[sev-1]}
            </div>
            {[1,2,3,4,5].map(lik=>{
              const score = lik * sev;
              const rl2 = riskLevel(lik, sev);
              const isSelected = L===lik && S===sev;
              return (
                <div key={lik}
                  onClick={()=>onChange({likelihood:lik, severity:sev})}
                  title={`L${lik} × S${sev} = ${score} (${rl2.label})`}
                  style={{
                    width:44, height:38,
                    background: isSelected ? rl2.color : rl2.bg,
                    border: isSelected ? `2px solid #fff` : `1px solid ${Z.borderMd}`,
                    cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
                    flexDirection:"column", gap:1, transition:"all .15s",
                    borderTop: sev<5 ? `1px solid ${Z.borderMd}` : "none",
                    borderLeft:`1px solid ${Z.borderMd}`,
                    boxSizing:"border-box",
                  }}>
                  <span style={{fontSize:11,fontWeight:800,color:isSelected?"#fff":rl2.text,lineHeight:1}}>{score}</span>
                  {isSelected && <span style={{fontSize:7,color:"#fff",fontWeight:700,lineHeight:1}}>▲</span>}
                </div>
              );
            })}
          </div>
        ))}
      </div>
      {/* Selected risk display */}
      {rl && (
        <div style={{marginTop:8,display:"flex",alignItems:"center",gap:10,padding:"8px 12px",borderRadius:8,background:rl.bg,border:`1px solid ${rl.color}44`}}>
          <div style={{width:10,height:10,borderRadius:2,background:rl.color,flexShrink:0}}/>
          <span style={{fontSize:12,fontWeight:700,color:rl.text}}>{rl.label} Risk</span>
          <span style={{fontSize:11,color:Z.muted}}>Score: {L*S} · Likelihood {L} × Severity {S}</span>
        </div>
      )}
    </div>
  );
}


